from pathlib import Path
import subprocess,sys,platform,json,hashlib,datetime
R=Path(__file__).resolve().parent
commands=[]
def run(cmd,log):
 p=subprocess.run(cmd,cwd=R,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 (R/log).write_text(p.stdout)
 commands.append({'argv':cmd,'cwd':str(R),'returncode':p.returncode,'output_file':log})
 if p.returncode: raise RuntimeError(f'{cmd[0]} failed: {log}')
 return p.stdout
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
run([sys.executable,'verify_sources.py'],'verify-sources.log')
run([sys.executable,'checks.py'],'exact-checks.log')
source=json.loads((R/'source-audit.json').read_text())
header='# P15.2: common full-mass domain and minimum full-form operator data\n\nAuthor: native Codex execution in the fresh assigned workspace. Date: 4 October 2026. Status: **partial**; unverified mathematical draft. The original P15.2 atom remains open. Only this atom is investigated; energy integrability is used solely to specify a common operator subdomain.\n\nThe new work is the scalar-deficit common-domain theorem, bare-current reconstruction, extension of the reference kernel to all full-mass inputs, quotient continuity and the explicit infinite-dimensional geometric-kernel example. Published foundations are cited with hypotheses and checked applications. Earlier supplied author/review verdicts are evidence to reconstruct, not theorem grants.\n\n'
proof=header+'\n\n'.join((R/f'proof-n{i}.md').read_text() for i in range(1,5))
(R/'P15.2-proof.md').write_text(proof)
run(['pandoc','P15.2-proof.md','--from=markdown+tex_math_dollars','--to=latex','--standalone','--variable=documentclass:article','--variable=fontsize:11pt','--variable=geometry:margin=1in','--variable=colorlinks:true','--output=P15.2-partial.tex'],'pandoc-build.log')
for k in [1,2]:
 run(['pdflatex','-interaction=nonstopmode','-halt-on-error','-file-line-error','P15.2-partial.tex'],f'pdflatex-pass-{k}.log')
run(['pdftotext','-layout','P15.2-partial.pdf','P15.2-partial-extracted.txt'],'pdftotext.log')
info=run(['pdfinfo','P15.2-partial.pdf'],'pdfinfo.log')
run(['pdftoppm','-f','1','-l','1','-scale-to','1400','-png','-singlefile','P15.2-partial.pdf','proof-first-page'],'pdf-first-page-render.log')
extracted=(R/'P15.2-partial-extracted.txt').read_text()
required=['Common full-mass','Bare-current','Minimum full-form','Perturbation limits','infinite-dimensional','partial']
assert all(s in extracted for s in required),[s for s in required if s not in extracted]
versions={}
for executable in ['pandoc','pdflatex','pdftotext']:
 p=subprocess.run([executable,'--version' if executable!='pdftotext' else '-v'],cwd=R,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 versions[executable]=p.stdout.splitlines()[0]
checks=json.loads((R/'exact-checks.json').read_text())
report={'recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'environment':{'python':sys.version,'platform':platform.platform(),'tools':versions},'commands':commands,'pdf_twice_compiled':True,'pdf_text_checks':{'required_strings':required,'all_found':True},'pdflatex_overfull_boxes':sum((R/f'pdflatex-pass-{k}.log').read_text().count('Overfull') for k in [1,2]),'exact_finite_diagnostics':checks,'source_pins':{'checked':source['range_pins_checked'],'matching':source['range_pins_matching']},'proof_sha256':sha(R/'P15.2-proof.md'),'tex_sha256':sha(R/'P15.2-partial.tex'),'pdf_sha256':sha(R/'P15.2-partial.pdf'),'evidence_status':'Execution, extraction, pins and finite arithmetic are observations only; none certifies analytic correctness.'}
(R/'build-audit.json').write_text(json.dumps(report,indent=2)+'\n')
audit=f'''# Execution and research audit\n\nThe unchanged input is `input.json` and its byte-identical `input-original.json`; SHA256 `{source['input_sha256']}` ({source['input_bytes']} bytes). `assignment-original.txt` retains the exact decoded assignment string; `task-original.json` retains its task values. The authoritative review deliverable is `P15.2-argument.md`, including every new proof and the complete indispensable primary bodies. `P15.2-proof.md` contains its authored proof portion. `P15.2-partial.tex` and `P15.2-partial.pdf` contain the entire new proof and all controlling theorem statements and applicability checks; raw printed bodies are in the Markdown annex to preserve UTF-8, form feeds, and defects.\n\nObserved source audit: {source['range_pins_matching']}/{source['range_pins_checked']} selected LF-range pins match. Fourteen primary supplied bodies also match their literal ranges and occur unchanged in the original assignment. DGMS/GZ text and PDF pins match. All 36 supplied fenced quotation strings are separately preserved in `supplied-quotation-archive.json`. `source-audit.json` records exact filenames, LF bounds, hashes, and boundary framing. Published foundations, source defect qualifications, and their applications are stated in the proof. The convergence of the bare current is additionally reconstructed by bounded cutoffs and capacity; no general unbounded-factor strengthening of Vu v3 Theorem 3.3 is used. No earlier proof or independent-worker output is used without reconstruction.\n\nObserved exact finite diagnostics: {checks['normalization_cases']} normalization cases and {checks['surface_wedge_cases']} formal surface wedge cases passed. These are exhaustive only on the program's stated finite inputs, not proofs of analytic results. Two `pdflatex` passes completed with return code zero; PDF text extraction found all required proof sections. The PDF SHA256 is `{report['pdf_sha256']}`. Build commands, outputs, environment versions and hashes are in `build-audit.json` and their named logs. Compilation is not mathematical certification.\n\nRequested execution identity: native Codex `gpt-6.1-sol`, reasoning `xhigh`. No model switching or additional model/subagent was invoked. The runtime does not provide a signed backend/effort attestation, so the requested identity is recorded as requested rather than independently certified. No network call, install, external message, auth/proxy/CA or HOME/CODEX_HOME change, SQL/runtime edit, or old-artifact write was performed. Source files were read only; new work is restricted to the fresh workspace. No resource-heavy computation was required. No operator-provided supervised compute facility was found among the available tools; heavy computation was neither attempted nor needed.\n\nResearch disposition: proposals 1 and 2 are proved in the common-domain scope; proposal 4 is proved with fixed smooth-factor and specified decreasing/mixed continuity, plus quantified quotient continuity and a concrete geometric kernel example. The purely definitional quotient step is explicitly distinguished from the new kernel extension. Proposal 3 belongs to the independently assigned energy problem and is not investigated. Optional degree-zero rigidity is not assumed. The full original P15.2 is not solved; status is partial and candidate is false.\n\nRerun from this directory: `python verify_sources.py`, `python checks.py`, `python build.py`, `python package_notes.py`. `status.json` has exactly the requested five keys. `notes.json` is the canonical native note object; support arrays contain earlier local IDs only. All drafts remain unverified; no literature-priority or external correctness certification is claimed.\n'''
(R/'execution-audit.md').write_text(audit)
(R/'P15.2-argument.md').write_text(proof+'\n\n'+audit+'\n\n'+(R/'source-annex.md').read_text())
print(f"build complete: two pdflatex passes, all PDF section checks, {source['range_pins_matching']}/{source['range_pins_checked']} source pins")
